function esperar(ms, valor) {
  return new Promise((resolve, reject) => {
    if (ms < 0) {
      reject(new Error("duração inválida"));
      return;
    }
    setTimeout(() => resolve(valor), ms);
  });
}

esperar(500, "concluído")
  .then((valor) => console.log(valor))
  .catch((erro) => console.error(erro.message));

function obterUtilizador(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id === 42) {
        resolve({ id: 42, nome: "Marta Silva" });
      } else {
        reject(new Error(`Utilizador ${id} não encontrado`));
      }
    }, 300);
  });
}

obterUtilizador(42)
  .then((utilizador) => utilizador.nome)
  .then((nome) => {
    console.log(`Nome: ${nome}`);
    return nome;
  })
  .catch((erro) => {
    console.error("Falha ao obter utilizador:", erro.message);
    return "Utilizador desconhecido";
  })
  .finally(() => {
    console.log("Pedido terminado");
  });

