function comTimeout(promessa, ms) {
  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error("Tempo excedido")), ms)
  );
  return Promise.race([promessa, timeout]);
}

comTimeout(esperar(2000, "dados"), 1000)
  .then((valor) => console.log(valor))
  .catch((erro) => console.error(erro.message)); // "Tempo excedido"

Promise.any([
  Promise.reject(new Error("espelho 1 falhou")),
  esperar(150, "resposta do espelho 2"),
  esperar(80, "resposta do espelho 3"),
])
  .then((primeiroSucesso) => console.log(primeiroSucesso)) // "resposta do espelho 3"
  .catch((erro) => {
    console.error(erro instanceof AggregateError, erro.errors);
  });

