function dividirAsync(a, b) {
  return new Promise((resolve, reject) => {
    if (b === 0) {
      reject(new Error("Divisão por zero"));
      return;
    }
    setTimeout(() => resolve(a / b), 500);
  });
}

dividirAsync(10, 2)
  .then((resultado) => console.log("Resultado:", resultado))
