function obterPreco(produtoId) {
  return new Promise((resolve, reject) => {
    if (produtoId < 1) {
      reject(new Error("ID de produto inválido"));
      return;
    }
    setTimeout(() => resolve(produtoId * 25), 300);
  });
}

obterPreco(3)
  .then((preco) => preco * 0.9)
  .then((precoComDesconto) => {
    console.log(`Preço final: ${precoComDesconto}€`);
  })
  .catch((erro) => {
    console.warn("Não foi possível obter o preço:", erro.message);
    return 0;
  })
  .finally(() => {
    console.log("Pedido de preço concluído");
  });

function verificarStock(produtoId) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(produtoId % 2 === 0), 200);
  });
}

function calcularPortes(produtoId) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(produtoId * 2), 150);
  });
}

function verificarStockPromocional(produtoId) {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error("Serviço promocional indisponível")), 100);
  });
}

function carregarDadosProduto(produtoId) {
  return Promise.allSettled([
    verificarStock(produtoId),
    calcularPortes(produtoId),
    verificarStockPromocional(produtoId),
  ]).then(([stockResult, portesResult, promocaoResult]) => ({
    stock: stockResult.status === "fulfilled" ? stockResult.value : null,
    portes: portesResult.status === "fulfilled" ? portesResult.value : null,
    promocao: promocaoResult.status === "fulfilled" ? promocaoResult.value : null,
  }));
}

carregarDadosProduto(4).then((dados) => console.log(dados));
// { stock: true, portes: 8, promocao: null }

function mirrorA() {
  return new Promise((resolve, reject) => {
    setTimeout(() => reject(new Error("mirrorA indisponível")), 120);
  });
}

function mirrorB() {
  return new Promise((resolve) => {
    setTimeout(() => resolve("resposta do mirrorB"), 200);
  });
}

function mirrorC() {
  return new Promise((resolve, reject) => {
    setTimeout(() => reject(new Error("mirrorC indisponível")), 80);
  });
}

function obterDadosMaisRapidos() {
  return Promise.any([mirrorA(), mirrorB(), mirrorC()]).catch((erro) => {
    console.error("Todos os espelhos falharam:");
    erro.errors.forEach((motivo, indice) => {
      console.error(`  espelho ${indice}: ${motivo.message}`);
    });
    throw erro;
  });
}

function obterComTimeout(promessa, limiteMs) {
  const timeout = new Promise((_, reject) => {
    setTimeout(() => reject(new Error("Tempo excedido")), limiteMs);
  });
  return Promise.race([promessa, timeout]);
}

obterComTimeout(obterDadosMaisRapidos(), 500)
  .then((resposta) => console.log("Resposta:", resposta))
  .catch((erro) => console.error("Falha final:", erro.message));
// "Resposta: resposta do mirrorB"
